SELECT  FROM chat_session WHERE 

  AND (updated_at < #{beforeTime} OR (updated_at=#{beforeTime} AND id < #{beforeId}))

ORDER BY updated_at DESC,id DESC LIMIT #{pageSize}

mapper.update:
UPDATE chat_session SET active_run_id=#{runId},run_deadline_at=#{deadline},
  next_message_seq=next_message_seq+2,updated_at=#{now}
WHERE  AND id=#{sessionId} AND status='ACTIVE' AND active_run_id IS NULL
  AND next_message_seq=#{expectedNextSeq} AND next_message_seq <= 9223372036854775805
  AND #{deadline} > #{now}

UPDATE chat_session SET active_run_id=NULL,run_deadline_at=NULL,updated_at=#{now}
WHERE  AND id=#{sessionId} AND active_run_id=#{runId}
  AND EXISTS (SELECT 1 FROM chat_message m WHERE m.merchant_id=#{owner.merchantId}
    AND m.session_id=#{sessionId} AND m.run_id=#{runId} AND m.sender_type='ASSISTANT'
    AND m.status IN ('COMPLETED','CANCELLED','TIMED_OUT','FAILED'))
